<script lang="ts">
  import { invoke } from '@tauri-apps/api/core';
  import { onMount } from 'svelte';
  import ItalyMap from './ItalyMap.svelte';
  import TripDetails from './TripDetails.svelte';
  import Weather from './Weather.svelte';
  import Planner from './Planner.svelte';
  import {romeToUtc} from './rome.js';
  import defaultRigs from '../content/lazio-rigs.v1.json';
  import defaultSectors from '../content/lazio-sectors.v1.json';
  type Trip = { id:number; title:string; starts_at:string; location:string; notes:string; outcome:string };
  type Package = {package_id:string,content_version:string,review_status:string,rigs:typeof defaultRigs,sectors:typeof defaultSectors};
  type PackageInfo = {package_id:string,content_version:string,region:string,active:boolean,imported_at:string};
  let rigContent=defaultRigs, sectorContent=defaultSectors; let currentPackage='Ricerca iniziale', packages:PackageInfo[]=[]; let packageMessage='';
  type Section = 'esplora' | 'pianifica' | 'diario' | 'dati';
  let section: Section = 'esplora';
  let trips: Trip[] = [];
  let title = '', date = '', location = '', notes = '', error = '', notice = '';
  let latestForecast:Record<string,unknown>|null = null;
  let selectedRig = 'A';
  let selectedRegion = 'Lazio';
  let selectedSector = sectorContent.sectors[0];
  let selectedTrip: number | null = null;
  let editingTrip: number | null = null;
  let editTitle='', editDate='', editLocation='', editNotes='';
  let backupMessage = '';
  let exportMessage = '';
  async function exportData(kind:string){try{const done=await invoke<boolean>('export_data',{kind});exportMessage=done?'Esportazione salvata.':'Esportazione annullata.'}catch(e){exportMessage=typeof e==='object' && e!==null && 'message' in e?String(e.message):'Esportazione non riuscita.'}}
  async function makeBackup() { try { const done = await invoke<boolean>('backup_database'); backupMessage = done ? 'Copia del database creata e verificata.' : 'Salvataggio annullato.'; } catch (e) { backupMessage = typeof e === 'object' && e !== null && 'message' in e ? String(e.message) : 'Impossibile creare la copia.'; } }
  async function restoreBackup() { try { const done = await invoke<boolean>('restore_database'); backupMessage = done ? 'Diario ripristinato. Una copia precedente è conservata localmente.' : 'Ripristino annullato.'; if (done) { selectedTrip = null; await loadTrips(); await refreshPackages(); } } catch (e) { backupMessage = typeof e === 'object' && e !== null && 'message' in e ? String(e.message) : 'Impossibile ripristinare la copia.'; } }
  $: rigs = rigContent.rigs;
  $: rig = rigs.find(r => r.id === selectedRig)!;
  async function refreshPackages() { if (!('__TAURI_INTERNALS__' in window)) return; try { const pack=await invoke<Package>('active_package');rigContent=pack.rigs;sectorContent=pack.sectors;currentPackage=`${pack.package_id} · ${pack.content_version}${pack.review_status==='draft'?' · preliminare':''}`;selectedSector=sectorContent.sectors[0];if(!rigContent.rigs.some(r=>r.id===selectedRig)) selectedRig=rigContent.rigs[0].id;packages=await invoke<PackageInfo[]>('list_packages'); } catch {packageMessage='Impossibile leggere il pacchetto di ricerca attivo.';} }
  async function importResearch(){try{const imported=await invoke<boolean>('import_package');packageMessage=imported?'Pacchetto importato e attivato.':'Importazione annullata.';if(imported)await refreshPackages()}catch(e){packageMessage=typeof e==='object'&&e!==null&&'message' in e?String(e.message):'Importazione non riuscita.'}}
  async function activateResearch(packageId:string,contentVersion:string){try{await invoke('activate_package',{packageId,contentVersion});await refreshPackages();packageMessage='Pacchetto attivato.'}catch(e){packageMessage=typeof e==='object'&&e!==null&&'message' in e?String(e.message):'Attivazione non riuscita.'}}
  async function loadTrips() { try { trips = await invoke<Trip[]>('list_trips'); error=''; } catch { error='Diario non disponibile. Avvia Sanpei come applicazione desktop.'; } }
  function editTrip(trip:Trip) { editingTrip=trip.id; editTitle=trip.title; editDate=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(trip.starts_at)); editLocation=trip.location; editNotes=trip.notes; }
  async function saveEdit() { if (editingTrip === null || !editDate || !editTitle.trim()) return; try { await invoke('update_trip',{tripId:editingTrip,trip:{title:editTitle,starts_at:romeToUtc(`${editDate}T12:00`),location:editLocation,notes:editNotes}}); editingTrip=null; await loadTrips(); } catch { error='Impossibile modificare l’uscita.'; } }
  async function deleteTrip(id:number) { if (!confirm('Eliminare questa uscita e tutti i suoi dettagli?')) return; try {await invoke('delete_trip',{tripId:id});selectedTrip=null;editingTrip=null;await loadTrips()} catch {error='Impossibile eliminare l’uscita.'} }
  async function saveTrip() {
    if (!title.trim() || !date) { error='Inserisci un titolo e una data.'; return; }
    try { const starts_at = romeToUtc(`${date}T12:00`); await invoke('create_trip', { trip: {title, starts_at, location, notes} }); title=''; date=''; location=''; notes=''; notice='Uscita salvata sul dispositivo.'; await loadTrips(); } catch { error='Impossibile salvare l’uscita.'; }
  }
  function displayDate(value:string) { const d = new Date(value); return Number.isNaN(d.getTime()) ? value : new Intl.DateTimeFormat('it-IT',{dateStyle:'long',timeZone:'Europe/Rome'}).format(d); }
  onMount(() => { if ('__TAURI_INTERNALS__' in window) {loadTrips();refreshPackages();} });
</script>

<svelte:head><title>Sanpei — diario di pesca</title><meta name="description" content="Pianifica e registra le tue uscite di pesca."></svelte:head>
<div class="app-shell">
  <aside class="sidebar">
    <div class="brand"><span class="brand-mark" aria-hidden="true">〰</span><span>sanpei<small>Diario di pesca</small></span></div>
    <nav aria-label="Navigazione principale">
      <button class:active={section==='esplora'} on:click={() => section='esplora'}><span aria-hidden="true">⌖</span> Esplora</button>
      <button class:active={section==='pianifica'} on:click={() => section='pianifica'}><span aria-hidden="true">◷</span> Pianifica</button>
      <button class:active={section==='diario'} on:click={() => section='diario'}><span aria-hidden="true">▤</span> Diario</button>
      <button class:active={section==='dati'} on:click={() => section='dati'}><span aria-hidden="true">⚙</span> Dati e impostazioni</button>
    </nav>
    <div class="side-note"><span class="dot"></span><div><strong>La tua base, sul dispositivo</strong><br><span>Il diario viene salvato in locale.</span></div></div>
  </aside>
  <main>
    <header class="topbar"><span>Sanpei <span class="slash">/</span> {section === 'dati' ? 'Dati e impostazioni' : section.charAt(0).toUpperCase()+section.slice(1)}</span><span class="top-status"><span class="dot"></span> Progetto in sviluppo</span></header>
    {#if section === 'esplora'}
      <section class="page explore">
        <div class="page-heading"><div><p class="overline">La costa, con criterio</p><h1>Esplora il Lazio</h1><p class="lead">Luoghi, tecniche e osservazioni per preparare la prossima uscita.</p></div><span class="region-label">Italia <span>›</span> Lazio</span></div>
        <div class="explore-grid">
          <ItalyMap onSelect={(name) => selectedRegion=name} />
          <div class="research-panel"><div class="section-kicker">La ricerca iniziale</div><h2>Prima l’habitat,<br>poi la distanza.</h2><p>Una buona presentazione dell’esca e una postazione accessibile contano più di una regola universale sulla luna o sulla distanza di lancio.</p><div class="research-rule"></div><h3>Da verificare sul posto</h3><ul><li>Accesso e ordinanze del tratto</li><li>Onde, corrente e tenuta del piombo</li><li>Avvisi ambientali aggiornati</li></ul><p class="source">Sintesi operativa della ricerca Lazio, versione 1.0. Le condizioni locali e la sicurezza alimentare richiedono verifiche specifiche.</p></div>
        </div>
        {#if selectedRegion === 'Lazio'}<section class="sectors"><div class="sectors-heading"><div><p class="small-label">Ricerca iniziale</p><h2>Settori da approfondire</h2><p>La ricerca descrive tratti candidati: queste schede non identificano postazioni precise né autorizzano l’accesso.</p></div></div><div class="sector-layout"><div class="sector-list">{#each sectorContent.sectors as sector}<button class:selected={selectedSector.id===sector.id} on:click={() => selectedSector=sector}>{sector.name}<span>›</span></button>{/each}</div><article class="sector-detail"><p class="small-label">Settore descritto · dati preliminari</p><h3>{selectedSector.name}</h3><h4>Habitat</h4><p>{selectedSector.habitat}</p><h4>Tecniche plausibili</h4><p>{selectedSector.techniques}</p><h4>Da verificare</h4><p>{selectedSector.caution}</p><p class="source">Ricerca critica Lazio, versione 1.0, 24 novembre 2026, sezioni 4–5. Evidenza operativa; fonti e geometrie da verificare. I dati ambientali non certificano il pescato.</p></article></div></section>{/if}
        <div class="bottom-callout"><div><span class="small-label">Il tuo quaderno</span><h2>Ogni uscita aggiunge contesto.</h2><p>Anche quando non si cattura nulla, un appunto può essere utile la prossima volta.</p></div><button class="primary" on:click={() => section='diario'}>Apri il diario <span>→</span></button></div>
      </section>
    {:else if section === 'pianifica'}
      <section class="page"><div class="page-heading"><div><p class="overline">La preparazione</p><h1>Montature e scelte</h1><p class="lead">Sei configurazioni operative da adattare alle condizioni reali.</p></div></div><div class="info-banner">Il confronto iniziale usa condizioni inserite da te e poche regole operative della ricerca; la specie resta un’annotazione.</div><Planner sectors={sectorContent} rigs={rigContent} forecastReference={latestForecast} onTripCreated={(id) => {section='diario';selectedTrip=id;loadTrips()}} /><Weather onForecast={(value) => latestForecast=value} /><div class="rig-layout"><div class="rig-list" aria-label="Montature">{#each rigs as item}<button class:selected={selectedRig===item.id} on:click={() => selectedRig=item.id}><span class="rig-id">{item.id}</span><span><strong>{item.name}</strong><small>{item.use}</small></span><span class="rig-arrow">›</span></button>{/each}</div><article class="rig-detail"><div class="rig-badge">Montatura {rig.id}</div><h2>{rig.name}</h2><p class="rig-use">{rig.use}</p><h3>Configurazione iniziale</h3><p>{rig.detail}</p><ul class="rig-components">{#each rig.components as component}<li>{component}</li>{/each}</ul><h3>Adattamenti</h3><p>{rig.adjustments}</p><h3>Da controllare</h3><p>{rig.caution}</p><p class="source">Ricerca Lazio, revisione 24 novembre 2026. Le misure sono configurazioni operative da adattare, non valori sperimentalmente ottimizzati.</p></article></div></section>
    {:else if section === 'diario'}
      <section class="page"><div class="page-heading"><div><p class="overline">Il tuo quaderno</p><h1>Diario delle uscite</h1><p class="lead">Conserva luogo, data e appunti sul tuo dispositivo.</p></div></div><div class="journal-layout"><form class="journal-form" on:submit|preventDefault={saveTrip}><h2>Nuova uscita</h2><p>Inizia con poche informazioni, poi aggiungi canne, intervalli e catture.</p><label>Titolo<input bind:value={title} required placeholder="Per esempio: uscita serale"></label><label>Data<input type="date" bind:value={date} required></label><label>Luogo <span>facoltativo</span><input bind:value={location} placeholder="Località o tratto"></label><label>Appunti <span>facoltativo</span><textarea bind:value={notes} rows="3" placeholder="Condizioni, idee o cose da ricordare"></textarea></label>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}<button class="primary" type="submit">Salva uscita</button></form><div class="entries"><div class="entries-heading"><h2>Le tue uscite</h2><span>{trips.length} {trips.length===1?'uscita':'uscite'}</span></div>{#if trips.length===0}<div class="empty"><div class="empty-icon">⌁</div><h3>Il diario è ancora vuoto</h3><p>La prima uscita inizia con un luogo e una data. Puoi registrarla anche al ritorno.</p></div>{:else}{#each trips as trip}<article class="entry"><div><span>{displayDate(trip.starts_at)}</span><h3>{trip.title}</h3><p>{trip.location || 'Luogo non indicato'}</p>{#if trip.notes}<p>{trip.notes}</p>{/if}</div><button class="outcome" on:click={() => selectedTrip = selectedTrip === trip.id ? null : trip.id}>{trip.outcome === 'zero' ? 'Nessuna cattura' : trip.outcome === 'catches' ? 'Catture' : 'Incompleta'} · Dettagli</button></article>{#if selectedTrip === trip.id}<div class="entry-actions"><button on:click={() => editTrip(trip)}>Modifica uscita</button><button on:click={() => deleteTrip(trip.id)}>Elimina uscita</button></div>{#if editingTrip === trip.id}<form class="compact-form edit-trip" on:submit|preventDefault={saveEdit}><label>Titolo<input bind:value={editTitle} required></label><label>Data<input type="date" bind:value={editDate} required></label><label>Luogo<input bind:value={editLocation}></label><label>Appunti<input bind:value={editNotes}></label><button type="submit">Salva modifiche</button><button type="button" on:click={() => editingTrip=null}>Annulla</button></form>{/if}<TripDetails tripId={trip.id} initialOutcome={trip.outcome} onChanged={loadTrips} />{/if}{/each}{/if}</div></div></section>
    {:else}
      <section class="page narrow"><div class="page-heading"><div><p class="overline">Il tuo dispositivo</p><h1>Dati e impostazioni</h1><p class="lead">Le informazioni del diario sono conservate in locale.</p></div></div><div class="settings-block"><h2>Conservazione</h2><p>Sanpei usa la cartella dati dell’applicazione sul computer. Crea o ripristina una copia del diario. Prima del ripristino, Sanpei conserva una copia locale dei dati correnti. Allegati ed esportazioni non sono ancora disponibili.</p><button class="primary" on:click={makeBackup}>Salva copia del database</button> <button class="secondary" on:click={restoreBackup}>Ripristina una copia</button>{#if backupMessage}<p role="status">{backupMessage}</p>{/if}</div><div class="settings-block"><h2>Esporta il diario</h2><p>Le esportazioni possono contenere note e coordinate personali. Scegli una destinazione che controlli. I CSV proteggono da formule interpretate dai fogli di calcolo aggiungendo un apostrofo ai valori che lo richiedono.</p><div class="export-buttons"><button class="secondary" on:click={() => exportData('json')}>JSON completo</button><button class="secondary" on:click={() => exportData('trips_csv')}>CSV uscite</button><button class="secondary" on:click={() => exportData('intervals_csv')}>CSV intervalli</button><button class="secondary" on:click={() => exportData('catches_csv')}>CSV catture</button><button class="secondary" on:click={() => exportData('geojson')}>GeoJSON posizioni</button></div>{#if exportMessage}<p role="status">{exportMessage}</p>{/if}</div><div class="settings-block"><h2>Ricerca attiva</h2><p>{currentPackage}. I pacchetti importati vengono controllati prima dell’attivazione; revisione e fonti restano responsabilità di chi prepara la ricerca.</p><button class="primary" on:click={importResearch}>Importa e attiva pacchetto JSON</button> <button class="secondary" on:click={() => activateResearch('lazio-iniziale','0.1.0')}>Usa ricerca iniziale</button>{#if packageMessage}<p role="status">{packageMessage}</p>{/if}{#if packages.length}<h3>Versioni importate</h3>{#each packages as pack}<div class="detail-row">{pack.package_id} · {pack.content_version} {pack.active?'(attiva)':''} <button on:click={() => activateResearch(pack.package_id,pack.content_version)} disabled={pack.active}>Attiva</button></div>{/each}{/if}</div><div class="settings-block"><h2>Fonti e contenuti</h2><p>La ricerca iniziale riguarda la pesca da riva nel Lazio. Informazioni ambientali, accessi e norme devono essere verificati prima dell’uscita.</p><p>Le schede riportano sintesi della ricerca, ancora da completare e verificare rispetto alle fonti originali.</p></div></section>
    {/if}
  </main>
</div>
